package com.autoops.workflow.entity;import jakarta.persistence.*;@Entity @Table(name="command_steps")public class CommandStep extends WorkflowStep{@Column(name="command_definition_id")private Long commandDefinitionId;@Column(name="command_template",nullable=false,columnDefinition="text")private String commandTemplate;@Column(name="parameters",columnDefinition="jsonb")private String parameters;@Column(name="run_with_sudo",nullable=false)private boolean runWithSudo;@Column(name="timeout_seconds",nullable=false)private Integer timeoutSeconds=60;}
